"""AST-only actual adapter/action integration with fake cores/motor/executor."""
from __future__ import annotations
import ast
from dataclasses import asdict, dataclass, replace
from hashlib import sha256
import json
from pathlib import Path
import time
from types import MappingProxyType, SimpleNamespace
import numpy as np

ROOT = Path(__file__).resolve().parents[1]
FILES = {
    "authority": "experiments/r4_integrated/contextual_rate_cell_python_session.py",
    "actions": "experiments/r4_integrated/contextual_evidence_python_session.py",
    "motor": "experiments/r4_integrated/contextual_pairwise_python_session.py",
    "fixture_helpers": "experiments/r4_integrated/contextual_full_choice_python_session.py",
    "conventional": "src/humanbrain/conventional_attention_reader.py",
    "rate": "src/humanbrain/rate_cell_reader.py",
}
def canonical(x):
    return json.dumps(x, sort_keys=True, separators=(",", ":"), allow_nan=False)
def digest(x):
    return sha256(canonical(x).encode()).hexdigest()
def selected(key, names, ns):
    tree = ast.parse((ROOT / FILES[key]).read_text(encoding="utf-8"))
    nodes = [n for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef)) and n.name in names]
    assert {n.name for n in nodes} == set(names)
    mod = ast.Module(body=[ast.ImportFrom(module="__future__", names=[ast.alias("annotations")], level=0), *nodes], type_ignores=[])
    exec(compile(ast.fix_missing_locations(mod), FILES[key], "exec"), ns)

ns = {"__name__": "__main__", "dataclass": dataclass, "asdict": asdict, "replace": replace,
      "sha256": sha256, "np": np, "json": json, "MappingProxyType": MappingProxyType,
      "canonical": canonical, "digest": digest, "time": time}
selected("authority", ("Decision", "ExecutedReader"), ns)
AuthorityReader = ns["ExecutedReader"]

class MotorReturnReader(AuthorityReader):
    def __init__(self, core, mode, inventory, queries):
        if mode not in ("trainable", "frozen_producer", "frozen", "conventional", "external"):
            raise ValueError("unknown motor-return policy")
        if any(raw != tokens.raw for raw, tokens in queries.items()):
            raise ValueError("query cache keys must match authenticated input bytes")
        self.core, self.mode, self.inventory = core, mode, inventory
        self.queries = MappingProxyType(dict(queries))
        self.feedback_root = digest({"scope": "public_qa_motor_return_inference_only"})
        self.training_pool = None  # inherited lesson validation always rejects feedback

calls, executions, learns = [], [], []
class FakeCore:
    def __init__(self, arm):
        self.arm, self.offer_count, self.update_count = arm, 2047, 1700
        self.weights = [0.25, -0.25]
        self.adam_steps = [1700] * 8
        self.mutate_prediction = False
    @property
    def checkpoint_sha256(self):
        return digest([self.arm, self.offer_count, self.update_count, self.weights, self.adam_steps])
    def snapshot(self):
        return {"checkpoint_sha256": self.checkpoint_sha256, "offer_count": self.offer_count,
                "update_count": self.update_count, "adam_steps": self.adam_steps.copy()}
    def result(self, tokens, inventory, method):
        assert len(inventory.documents) == 16
        calls.append((self.arm, method, tokens.raw.decode(), inventory.sha256))
        if self.mutate_prediction:
            self.offer_count += 1
        stop = b"stop" in tokens.raw
        return SimpleNamespace(candidate_index=None if stop else 0, stop_reason="answerability_STOP" if stop else None,
                               p_stop=0.9 if stop else 0.1, stop_logit=1.0 if stop else -1.0,
                               span_scores=np.array([1.0]))
    def predict(self, tokens, inventory):
        return self.result(tokens, inventory, "predict")
    def external_only(self, tokens, inventory):
        return self.result(tokens, inventory, "external_only")

class FakeCase:
    def __init__(self, name, key, value, module, stale):
        self.name, self.key, self.value, self.module, self.stale = name, key, value, module, stale
    def files(self, corrected=False):
        return (self.name, self.value if corrected else self.stale, "decoy")
class FakeMotor:
    def __init__(self): self.learned = 0
    @property
    def checkpoint_sha256(self): return digest(self.learned)
    @property
    def demonstration_count(self): return self.learned
    @property
    def retained_demonstration_event_bytes(self): return self.learned * 10
    def learn(self, request, before, after):
        learns.append((request.decode(), before, after)); self.learned += 1
    def apply(self, request, before, replacement):
        return SimpleNamespace(files=(before[0], replacement.decode(), before[2]), edited=True, stop_reason=None,
                               request_seed_count=2, supported_role_count=1, physical_cell_steps=5,
                               evaluated_cells=4, checkpoint_sha256=self.checkpoint_sha256)
mutate_during_execution = None
def execute(case, files, before, root):
    executions.append(str(root))
    if mutate_during_execution is not None:
        mutate_during_execution.adam_steps[0] += 1
    return {"passed": files[1] == case.value, "decoys_unchanged": files[2] == before[2]}

ns.update(Case=FakeCase, execute=execute)
selected("actions", ("decision_record", "attempt"), ns)
selected("fixture_helpers", ("_item", "_summary"), ns)
shared = SimpleNamespace(Case=FakeCase, execute=execute)
motor_ns = {"__name__": "__main__", "shared": shared, "ContextualOccurrenceMotor": FakeMotor}
selected("motor", ("_motor",), motor_ns)
report = {}
motor = motor_ns["_motor"](Path("synthetic-workspaces"), report)
assert len(learns) == len(executions) == 2

inventory = SimpleNamespace(sha256="complete-sixteen-source-root", documents=tuple(range(16)),
                            candidates=(SimpleNamespace(emitted=b"whole multi word value"),))
tasks = [{"id": f"synthetic-{i}", "query": f"{'answer' if i < 48 else 'stop'} request {i}",
          "answer": "whole multi word value" if i < 48 else None,
          "workspace": {"key": "key", "module": "module", "stale": "stale"},
          "property": "role", "query_form_group": "form", "expected_source_id": "EVALUATOR_ONLY"}
         for i in range(64)]
queries = {raw.encode(): SimpleNamespace(raw=raw.encode(), sha256=digest(raw))
           for task in tasks for raw in (task["query"], "alternate " + task["query"])}
cores = {a: FakeCore(a) for a in ("trainable", "frozen_producer", "frozen", "conventional", "external")}
adapters = {a: MotorReturnReader(c, a, inventory, queries) for a, c in cores.items()}
queries.clear()
before = {a: c.snapshot() for a, c in cores.items()}
summaries = {}
for phase in ("actual", "alternate"):
    summaries[phase] = {}
    for arm, adapter in adapters.items():
        assert adapter.core is cores[arm]
        rows = []
        for task in tasks:
            query = task["query"] if phase == "actual" else "alternate " + task["query"]
            row, decision = ns["attempt"](adapter, "respond", motor, ns["_item"](task, query),
                                           Path("synthetic-workspaces") / phase / arm / task["id"])
            assert row["selection"]["mode"] == arm
            assert row["selection"]["query_input_sha256"] == adapter.queries[query.encode()].sha256
            assert decision.sha256 == digest(replace(decision, sha256="").record())
            rows.append(row)
        summaries[phase][arm] = ns["_summary"](rows, tasks)
assert len(calls) == 640 and len(executions) == 642 and len(learns) == 2
assert before == {a: c.snapshot() for a, c in cores.items()}
assert all(method == ("external_only" if arm == "external" else "predict") for arm, method, _, _ in calls)

errors = []
try:
    MotorReturnReader(cores["trainable"], "trainable", inventory, {b"wrong": SimpleNamespace(raw=b"right")})
except ValueError: errors.append("mismatched_query_cache_rejected")
core = cores["trainable"]
core.mutate_prediction = True
try:
    adapters["trainable"].respond(tasks[0]["query"].encode())
except RuntimeError: errors.append("prediction_mutation_rejected")
core.mutate_prediction = False
mutate_during_execution = core
try:
    ns["attempt"](adapters["trainable"], "respond", motor, ns["_item"](tasks[0], tasks[0]["query"]), Path("mutation"))
except RuntimeError: errors.append("execution_time_core_mutation_rejected")
assert len(errors) == 3

tree = ast.parse((ROOT / FILES["conventional"]).read_text(encoding="utf-8"))
cls = next(n for n in tree.body if isinstance(n, ast.ClassDef) and n.name == "ConventionalAttentionReader")
assert [ast.unparse(x) for x in cls.bases] == ["RateCellReader"]
methods = {n.name for n in cls.body if isinstance(n, ast.FunctionDef)}
assert "predict" not in methods and "external_only" not in methods and "checkpoint_sha256" not in methods
assert "checkpoint_arrays" in methods and "snapshot" in methods
source_hashes = {p: sha256((ROOT / p).read_bytes()).hexdigest() for p in FILES.values()}
result = {"status": "passed", "scope": "AST actual-source adapter/action/motor helpers; synthetic fake core, motor and executor only",
          "actual_model_native_motor_training_calls": 0, "synthetic_attempts": 640, "synthetic_demo_executions": 2,
          "trained_core_identity_preserved": True, "snapshot_and_counters_unchanged": True,
          "complete_source_pool_passed": True, "query_cache_copy_verified": True,
          "decision_hash_and_arm_labels_verified": True, "conventional_inherited_prediction_contract": True,
          "red_checks": errors, "source_sha256": source_hashes,
          "adapter_source": ast.get_source_segment(Path(__file__).read_text(), next(n for n in ast.parse(Path(__file__).read_text()).body if isinstance(n, ast.ClassDef) and n.name == "MotorReturnReader"))}
out = ROOT / ".pytest-tmp" / "public-qa-motor-return-qa.json"
out.write_text(json.dumps(result, indent=2) + "\n", encoding="utf-8", newline="\n")
print(json.dumps({"path": str(out), "sha256": sha256(out.read_bytes()).hexdigest(), "status": "passed"}))

